function renderRibbon(){const tab=RIBBON.find(r=>r.id===(S.ribbonTab||'home'))||RIBBON[0];
  const cls=document.body.classList,peekOn=cls.contains('ribbonPeek'),collapsed=!!S.prefs.ribbonCollapsed;
  $('ribbonTabs').innerHTML=`<button class="fileBtn" data-file-menu>File</button>`+RIBBON.map(r=>`<button data-rtab="${r.id}" class="${r===tab&&(!collapsed||peekOn)?'active':''}" title="${collapsed?'Click to show · double-click to pin the ribbon':'Double-click to collapse the ribbon (Ctrl+F1)'}">${r.name}</button>`).join('')+
    `<span class="spacer"></span>${S.prefs.showHeader===false?`<span class="tabDoc" title="${html(S.doc.name)}">${html(S.doc.name)}</span>`:''}<span class="chromeBtns">${[['toggleLeft','sideL','Shapes panel (Ctrl+Alt+←)',narrowScreen()?document.body.classList.contains('showLeft'):S.prefs.leftOpen],['toggleRight','sideR','Inspector (Ctrl+Alt+→)',narrowScreen()?document.body.classList.contains('showRight'):S.prefs.rightOpen],['toggleRibbon',collapsed?'ribbonDown':'ribbonUp',collapsed?'Pin the ribbon open (Ctrl+F1)':'Collapse the ribbon (Ctrl+F1)',!collapsed],['toggleHeader','titleBar','Title bar',S.prefs.showHeader!==false],['toggleStatus','statusBar','Status bar & page tabs',S.prefs.showStatus!==false],['focusMode','focus','Focus mode — canvas only (Ctrl+.)',document.body.classList.contains('focus')]].map(([a,ic,t,on])=>`<button data-action="${a}" class="${on?'on':''}" title="${t}">${icon(ic,15)}</button>`).join('')}</span>`;
  $('ribbon').innerHTML=tab.groups.map(g=>`<div class="rgroup"><div class="ritems">${g.items.map(i=>{if(i.t==='html')return i.fn();const big=i.big?' big':'';if(i.t==='mode')return`<button data-mode="${i.mode}" class="rbtn${big} ${S.mode===i.mode?'active':''}" title="${i.label} (${i.key})">${icon(i.icon,i.big?22:16)}<span>${i.label}</span></button>`;if(i.t==='toggle')return`<button data-action="toggle_${i.pref}" class="rbtn ${S.prefs[i.pref]?'active':''}" title="${i.label}">${icon(i.icon,16)}<span>${i.label}</span></button>`;return`<button data-action="${i.action}" class="rbtn${big}" title="${html(i.title||i.label)}">${icon(i.icon,i.big?22:16)}<span>${i.label}</span></button>`}).join('')}</div><div class="rname">${g.name}</div></div>`).join('')}
const FILE_MENU=[['new','New from template…','template','Ctrl+N'],['newBlank','New blank drawing','file'],['insertTemplate','Add template to this drawing…','template'],['saveTemplate','Save as template…','save'],['newRevision','New revision…','delta'],['myDrawings','My drawings (this browser)…','open'],['open','Open file…','open','Ctrl+O'],['save','Save','save','Ctrl+S'],['saveAs','Save as…','save','Ctrl+Shift+S'],'-',['exportVsdx','Export to Visio (.vsdx)','visio'],['exportDrawio','Export to draw.io','drawio'],['exportSvg','Export page as SVG','export'],['exportPng','Export page as PNG (2×)','image','Ctrl+E'],['exportPng4','Export page as PNG (4×, print)','image'],['exportPngT','Export PNG with transparent background','image'],['copyPng','Copy page as image','copy'],'-',['print','Print / PDF…','print','Ctrl+P'],['printAll','Print all pages…','print'],['share','Copy share link','share'],['downloadOffline','Download offline edition (one HTML file)','export'],'-',['docProps','Document properties','fields'],['importShapes','Import shapes / icon pack…','import'],['managePacks','Shape packs…','layers'],['importLibrary','Import symbol library…','import'],['exportLibrary','Export symbol library','export']];
function openFileMenu(btn){const m=$('fileMenu');m.innerHTML=FILE_MENU.map(i=>i==='-'?'<hr>':`<button data-action="${i[0]}">${icon(i[2],16)}<span>${i[1]}</span>${i[3]?`<kbd>${i[3]}</kbd>`:''}</button>`).join('');const r=btn.getBoundingClientRect();showMenu(m,r.left,r.bottom+4)}

// ---------- left panel ----------
function renderLeft(){const tab=S.ltab||'shapes';document.querySelectorAll('[data-ltab]').forEach(b=>b.classList.toggle('active',b.dataset.ltab===tab));$('shapesPane').hidden=tab!=='shapes';$('iconsPane').hidden=tab!=='icons';$('layersPane').hidden=tab!=='layers';$('templatesPane').hidden=tab!=='templates';$('explorerPane').hidden=tab!=='explorer';if(tab==='icons')setTimeout(()=>$('iconSearch')?.focus(),20);if(tab==='shapes')renderPalette();if(tab==='layers')renderLayers();if(tab==='templates'){TplLib.invalidate();TplLib.render()}if(tab==='explorer')renderExplorer()}
function renderPalette(){
  const q=($('search')?.value||'').toLowerCase().trim(),display=S.prefs.paletteDisplay||'symbol',DEFAULT_OPEN=new Set(['_recent','_lib','network','security','compute','cloud','endpoints','surveillance','sites','rack']),isOpen=id=>S.prefs.catOpen?.[id]??(DEFAULT_OPEN.has(id)||id.startsWith('pack:')&&!id.startsWith('pack:online')),total=Object.keys(Stencils.shapes).length+Object.keys(Shapes.basic).length+Object.keys(Shapes.rackItems).length+3;$('search').placeholder=`Search ${total} shapes — fw, nvr, ap…`;
  const match=i=>!q||(i.name+' '+i.type+' '+i.tags).toLowerCase().includes(q);
  const cell=i=>`<button class="stencil" draggable="true" data-symbol="${i.type}" title="${html(i.name)} — click or drag onto the page">${Shapes.iconSvg(i.type,{display:Shapes.kindOf(i.type)==='device'?display:'symbol',size:40})}<span>${html(i.name)}</span></button>`;
  let out='';const cats=Shapes.catalog();
  const recent=(S.prefs.recent||[]).map(t=>cats.flatMap(c=>c.items).find(i=>i.type===t)).filter(Boolean);
  if(recent.length&&!q)out+=`<details class="cat" ${isOpen('_recent')?'open':''} data-cat="_recent"><summary>Recently used</summary><div class="palette">${recent.map(cell).join('')}</div></details>`;
  for(const c of cats){const list=c.items.filter(match).slice(0,q?400:2000);if(!list.length)continue;const open=q||isOpen(c.id);out+=`<details class="cat${c.pack?' packCat':''}" data-cat="${c.id}" ${open?'open':''}><summary>${html(c.name)} <em>${list.length}</em></summary><div class="palette">${open?list.map(cell).join(''):''}</div></details>`}
  const lib=S.library.filter(e=>!q||e.name.toLowerCase().includes(q));
  out+=`<details class="cat" data-cat="_lib" open><summary>My library <em>${S.library.length}</em></summary>${lib.map(e=>`<div class="portrow"><button class="libItem" draggable="true" data-library="${e.id}">${html(e.name)}</button><button data-library-delete="${e.id}" title="Remove">×</button></div>`).join('')||'<p class="muted">Select shapes and use Insert ▸ Save to library. Imported images and custom groups can be reused here.</p>'}<div class="row">${'<button data-action="importLibrary">Import…</button><button data-action="exportLibrary">Export</button>'}</div></details>`;
  if(!out)out='<p class="muted pad">No shapes match “'+html(q)+'”.</p>';$('palette').innerHTML=out}
function renderLayers(){const L=S.doc.layers,counts=new Map();for(const n of items()){const id=layerOf(n)?.id;counts.set(id,(counts.get(id)||0)+1)}
  $('layersPane').innerHTML=`<p class="muted">Layers are shared by all pages. New shapes go on the active layer (●). Hidden layers don't print; non-printing layers show on screen only.</p><div class="layerList">${L.map(l=>`<div class="layer ${S.activeLayer===l.id?'active':''}" data-layer="${l.id}"><button data-layer-active="${l.id}" title="Make active">${S.activeLayer===l.id?'●':'○'}</button><input data-layer-name="${l.id}" value="${html(l.name)}"><span class="muted">${counts.get(l.id)||0}</span><button data-layer-toggle="visible" data-id="${l.id}" class="${l.visible!==false?'on':''}" title="Visible">👁</button><button data-layer-toggle="locked" data-id="${l.id}" class="${l.locked?'on':''}" title="Locked">🔒</button><button data-layer-toggle="print" data-id="${l.id}" class="${l.print!==false?'on':''}" title="Printable">🖨</button><button data-layer-select="${l.id}" title="Select all on this layer">⬚</button><button data-layer-delete="${l.id}" title="Delete layer">×</button></div>`).join('')}</div><div class="row"><input id="newLayer" placeholder="New layer name"><button data-action-layer-add>＋ Add</button></div><button data-layer-assign class="wide">Move selection to active layer</button><div class="row"><button data-layer-preset>Add network presets</button><button data-layer-solo>Show all</button></div>`}
function renderExplorer(){const q=($('explorerSearch')?.value||'').toLowerCase();const groups=[['zone','Zones'],['node','Devices & shapes'],['edge','Connectors'],['text','Text'],['table','Tables'],['legend','Legends']];
  const body=S.doc.pages.map((p,pi)=>{const its=p.items.filter(n=>{const name=(n.kind==='edge'?edgeName(n,p):Analysis.nameOf(n))+' '+Object.values(n.data||{}).join(' ');return!q||name.toLowerCase().includes(q)});return`<details class="cat" ${pi===S.pageIndex||q?'open':''}><summary>${p.isBackground?'▧ ':''}${html(p.name)} <em>${its.length}</em></summary>${groups.map(([k,t])=>{const list=its.filter(n=>n.kind===k);if(!list.length)return'';return`<div class="exGroup">${t}</div>`+list.slice(0,400).map(n=>`<button class="exItem ${S.selected.has(n.id)&&pi===S.pageIndex?'active':''}" data-explore="${pi}:${n.id}">${n.kind==='node'?Shapes.iconSvg(n.type,{size:20}):''}<span>${html(n.kind==='edge'?edgeName(n,p):Analysis.nameOf(n)||'('+n.kind+')')}</span>${n.data?.ip?`<em>${html(n.data.ip)}</em>`:''}</button>`).join('')}).join('')}</details>`}).join('');
  $('explorerList').innerHTML=body||'<p class="muted pad">Nothing here yet.</p>'}
function edgeName(e,p){const n=id=>p.items.find(i=>i.id===id);return`${e.from?Analysis.nameOf(n(e.from.node)):'·'} ↔ ${e.to?Analysis.nameOf(n(e.to.node)):'·'}`}

// ---------- page tabs, status, chrome ----------
function renderChrome(){
  $('pageTabs').innerHTML=S.doc.pages.map((p,i)=>`<button data-page="${i}" draggable="true" class="${i===S.pageIndex?'active':''} ${p.isBackground?'bgTab':''}" title="${p.isBackground?'Background page':'Double-click to rename · right-click for options'}">${p.isBackground?'▧ ':''}${html(p.name)}</button>`).join('')+'<button data-action="addPage" title="Add page" class="addTab">＋</button>';
  if(document.activeElement!==$('docName'))$('docName').value=S.doc.name;document.title=S.doc.name+' · Port Network Studio';
  const sel=picked();$('selectionCount').textContent=sel.length?`${sel.length} selected${sel.length===1&&sel[0].kind!=='edge'?` · ${Math.round(sel[0].w/C.PX)}×${Math.round(sel[0].h/C.PX)} mm`:''}`:`${items().length} objects`;
  $('pageInfo').textContent=`${pg().paper==='Custom'?pg().customW+'×'+pg().customH+' mm':pg().paper} · ${pg().orientation}`;$('zoomValue').textContent=Math.round(S.view.zoom*100)+'%';$('zoomRange').value=Math.round(Math.log2(S.view.zoom)*100);
  $('layerSel').innerHTML=S.doc.layers.map(l=>`<option value="${l.id}" ${S.activeLayer===l.id?'selected':''}>${html(l.name)}</option>`).join('');
  $('undoBtn')?.toggleAttribute('disabled',!S.history.length);
  document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===S.mode));
  if(S.ltab==='explorer'&&!$('explorerPane').hidden)renderExplorer();if(S.ltab==='layers'&&!$('layersPane').hidden&&!$('layersPane').contains(document.activeElement))renderLayers();
  const ls=$('linkTypeSel');if(ls&&ls.value!==S.linkType)ls.value=S.linkType;const cb=$('colorBySel');if(cb)cb.value=S.doc.display.colorBy||'';
  if(S.ribbonTab==='design'||S.ribbonTab==='data'){const keep=document.activeElement?.closest?.('#ribbon');if(!keep)renderRibbon()}}

// ---------- dialogs ----------
function openDialog(title,body,{wide=false,modeless=false,cls=''}={}){const d=$('dlg');d.className=(wide?'wide ':'')+(modeless?'floating ':'')+cls;d.innerHTML=`<header><h2>${title}</h2><button class="x" data-close>×</button></header><div class="dlgBody">${body}</div>`;if(d.open)d.close();modeless?d.show():d.showModal();return d}
function closeDialog(){const d=$('dlg');if(d.open)d.close()}
function openTemplates(mode){mode??=S.prefs.tplMode==='add'&&items().length?'add':'new';const list=Templates.list(),mine=TplLib.list();
  const cardsFor=add=>`${add?'':'<button class="tpl" data-tpl="_blank"><div class="thumb blank">＋</div><b>Blank drawing</b><span>A3 landscape, empty</span></button>'}${list.map(t=>`<button class="tpl" data-tpl="b:${t.id}"><div class="thumb" data-thumb="b:${t.id}"></div><b>${html(t.name)}</b><span>${html(t.description)}</span></button>`).join('')}${mine.map(t=>`<button class="tpl" data-tpl="u:${t.id}"><div class="thumb" data-thumb="u:${t.id}"></div><b>${html(t.name)}</b><span>My template${t.description?' · '+html(t.description):''}</span></button>`).join('')}`;
  const d=openDialog('Templates',`<div class="seg tplMode"><button data-tpl-mode="new" class="${mode==='new'?'active':''}">Open as a new drawing</button><button data-tpl-mode="add" class="${mode==='add'?'active':''}">Add to this drawing</button></div><p class="muted" id="tplModeHint"></p><div class="tplGrid" id="tplGrid"></div>`,{wide:true});
  const draw=()=>{$('tplModeHint').innerHTML=mode==='add'?'Pick a template to add to <b>'+html(S.doc.name)+'</b> — next you choose a page or zone, where it goes and how subnets, layers and the legend merge. You can also drag templates from the <b>Templates</b> tab in the left panel.':'Start a new drawing from a template — every one is fully editable, with real shape data, zones and auto-routed links. Your current drawing stays in File ▸ My drawings.';
    $('tplGrid').innerHTML=cardsFor(mode==='add');requestAnimationFrame(async()=>{for(const host of d.querySelectorAll('[data-thumb]')){try{const doc=await TplLib.docOf(host.dataset.thumb);if(doc&&!host.firstChild){Packs.installDoc(doc);host.append(thumbnail(doc,doc.pages.find(p=>!p.isBackground)||doc.pages[0],260,165))}}catch(err){console.warn(err)}await new Promise(r=>setTimeout(r,0))}})};draw();
  d.onclick=async e=>{if(e.target.closest('[data-close]'))return closeDialog();const m=e.target.closest('[data-tpl-mode]');if(m){mode=m.dataset.tplMode;S.prefs.tplMode=mode;savePrefs();d.querySelectorAll('[data-tpl-mode]').forEach(b=>b.classList.toggle('active',b===m));draw();return}
    const b=e.target.closest('[data-tpl]');if(!b)return;const key=b.dataset.tpl;
    if(mode==='add'){closeDialog();TplLib.openAdd({src:key});return}
    if(S.dirty&&!confirm('Replace the current drawing? Unsaved changes can be restored with Undo.'))return;closeDialog();
    if(key==='_blank')return loadDocument(C.newDoc(),{name:'template'});const doc=await TplLib.docOf(key);if(!doc)return;loadDocument(C.copy(doc),{name:'template'});notify('Template loaded. Try Analyze ▸ Check diagram, or Data ▸ Reports.',4500)}}
