function renamePage(){const v=prompt('Page name',pg().name);if(v?.trim())mutate(()=>pg().name=v.trim())}

// ---------- theme & layout prefs ----------
function applyUiTheme(){const t=S.prefs.theme,dark=t==='dark'||t==='auto'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';render()}
// Phones: side panels are overlays opened from the tab-row buttons, not grid columns.
const narrowScreen=()=>matchMedia('(max-width:860px)').matches;
function overlayPanel(side){const c=document.body.classList,k=side==='left'?'showLeft':'showRight',on=!c.contains(k);c.remove('showLeft','showRight');c.toggle(k,on);if(on&&side==='left')renderLeft();renderRibbon()}
function applyLayoutPrefs(){const c=document.body.classList;c.toggle('noLeft',!S.prefs.leftOpen);c.toggle('noRight',!S.prefs.rightOpen);c.toggle('noHeader',S.prefs.showHeader===false);c.toggle('ribbonCollapsed',!!S.prefs.ribbonCollapsed);if(!S.prefs.ribbonCollapsed)c.remove('ribbonPeek');c.toggle('noStatus',S.prefs.showStatus===false);if(S.doc)renderRibbon();setTimeout(()=>{render();checkLayout()},60)}
function setChrome(k,v){S.prefs[k]=v;savePrefs();applyLayoutPrefs()}
const CHROME_DEFAULTS={leftOpen:true,rightOpen:true,showHeader:true,ribbonCollapsed:false,showStatus:true};
function resetLayout(quiet){Object.assign(S.prefs,CHROME_DEFAULTS);delete S.prefs.beforeFocus;document.body.classList.remove('focus','ribbonPeek','presenting');savePrefs();applyLayoutPrefs();if(!quiet)notify('Layout reset: title bar, ribbon, panels and status bar restored.')}
// Safety net: if any layout choice ever leaves the canvas without room, put the default layout back.
function checkLayout(){const w=$('workarea')?.getBoundingClientRect();if(!w||innerHeight<300||innerWidth<500)return;if(w.height<120||w.width<160){resetLayout(true);notify('The canvas had no room, so the layout was reset. View ▸ Layout has the options; Ctrl+. toggles focus mode.',6000)}}
function presentStep(dir){const fg=S.doc.pages.map((p,i)=>[p,i]).filter(([p])=>!p.isBackground).map(x=>x[1]),k=fg.indexOf(S.pageIndex),next=fg[Math.max(0,Math.min(fg.length-1,k+dir))];if(next!==undefined&&next!==S.pageIndex)gotoPage(next)}

// ---------- legend generator ----------
function openLegend(){
  const sel=picked().find(n=>n.kind==='legend'),existing=sel||items().find(n=>n.kind==='legend'),o={title:'LEGEND',scope:'page',devices:true,links:true,zones:false,colors:true,status:true,counts:true,maxRows:8,place:'bl',...(existing?{title:existing.title,scope:existing.scope||'page',devices:existing.devices!==false,links:existing.links!==false,zones:!!existing.zones,colors:existing.colors!==false,status:existing.status!==false,counts:existing.counts!==false,maxRows:existing.maxRows||8,place:existing.pin||'free'}:{})};
  const opt=(v,t,cur)=>`<option value="${v}" ${String(cur)===String(v)?'selected':''}>${t}</option>`,ck=(k,t)=>`<label class="check"><input type="checkbox" data-lg="${k}" ${o[k]?'checked':''}>${t}</label>`;
  const d=openDialog('Legend generator',`<p class="muted">${existing?'Updates the legend on this page'+(sel?' (selected)':'')+'.':'Adds a legend to this page.'} Legends rebuild themselves from the drawing whenever it changes.</p>
  <div class="row"><label class="fld"><span>Title</span><input data-lg="title" value="${html(o.title)}"></label><label class="fld"><span>Covers</span><select data-lg="scope">${opt('page','This page',o.scope)}${opt('doc','Whole drawing (all pages)',o.scope)}</select></label></div>
  <div class="fld"><span>Include</span><div class="checks">${ck('devices','Device types (as drawn)')}${ck('links','Link types')}${ck('zones','Zones')}${ck('colors','Colour-by values')}${ck('status','Planned / to-remove marks')}${ck('counts','Counts')}</div></div>
  <div class="row"><label class="fld"><span>Rows per column</span><input data-lg="maxRows" type="number" min="3" max="40" value="${o.maxRows}"></label><label class="fld"><span>Placement</span><select data-lg="place">${opt('bl','Pinned bottom-left',o.place)}${opt('br','Pinned bottom-right',o.place)}${opt('tl','Pinned top-left',o.place)}${opt('tr','Pinned top-right',o.place)}${opt('free','Free (where it is / centre of view)',o.place)}</select></label></div>
  <div class="legendPreview" id="lgPreview"></div>
  <footer><button data-close>Cancel</button><button data-lg-all>Add to every page</button><button class="primary" data-lg-apply>${existing?'Update legend':'Create legend'}</button></footer>`);
  const read=()=>{const r={...o};d.querySelectorAll('[data-lg]').forEach(i=>{r[i.dataset.lg]=i.type==='checkbox'?i.checked:i.type==='number'?Math.max(3,+i.value||8):i.value});return r};
  const props=r=>({title:r.title||'LEGEND',scope:r.scope,devices:r.devices,links:r.links,zones:r.zones,colors:r.colors,status:r.status,counts:r.counts,maxRows:r.maxRows});
  const preview=()=>{const r=read(),t={id:'preview',kind:'legend',x:0,y:0,w:10,h:10,labels:[],...props(r)},svg=document.createElementNS(NS,'svg'),ctx=makeCtx(pg());RCTX=ctx;drawLegend(t,el('g',{},svg),ctx,pg());RCTX=null;svg.setAttribute('viewBox',`-2 -2 ${t.w+4} ${t.h+4}`);svg.setAttribute('width',Math.min(560,t.w));$('lgPreview').replaceChildren(svg);if(!legendRows(t,pg(),ctx).length)$('lgPreview').insertAdjacentHTML('beforeend','<p class="muted">Nothing to list yet with these options.</p>')};
  const placeOn=(page,l,place)=>{RCTX=makeCtx(page);legendMeasure(l,page,RCTX);RCTX=null;if(place==='free'){delete l.pin;return}l.pin=place;Constraints.place(l,Constraints.area(page),{l:10,r:10,t:10,b:10})};
  d.oninput=preview;d.onchange=preview;preview();
  d.onclick=e=>{if(e.target.closest('[data-close]'))return closeDialog();const r=read();
    if(e.target.closest('[data-lg-apply]')){closeDialog();mutate(()=>{let l=existing;if(!l){const c=centerOfView();l={id:C.uid(),kind:'legend',x:c[0]-100,y:c[1]-60,w:200,h:120,labels:[],layer:S.activeLayer};items().push(l)}Object.assign(l,props(r));if(r.place!=='free'||!existing)placeOn(pg(),l,r.place);else delete l.pin;select([l.id])});notify('Legend '+(existing?'updated':'created')+'. It keeps itself up to date as the drawing changes.')}
    if(e.target.closest('[data-lg-all]')){closeDialog();let k=0;mutate(()=>{for(const p of S.doc.pages){if(p.isBackground||p.items.some(i=>i.kind==='legend'))continue;const l={id:C.uid(),kind:'legend',x:0,y:0,w:200,h:120,labels:[],layer:S.activeLayer,...props(r)};p.items.push(l);placeOn(p,l,r.place==='free'?'bl':r.place);k++}});notify(k?`Legend added to ${k} page(s).`:'Every page already has a legend.')}}}

// ---------- fit page to drawing ----------
function openFitPage(){
  const p=pg(),o={...Constraints.FIT_DEFAULTS,...p.fit,margin:p.margin,keep:p.autoSize==='fit'};
  const opt=(v,t,cur)=>`<option value="${v}" ${String(cur)===String(v)?'selected':''}>${t}</option>`;
  const d=openDialog('Fit page to drawing',`<p class="muted">Resizes the page — and the border and title block that follow it — around what is on the page.</p>
  <div class="fld"><span>Page size</span><div class="seg fitMode"><button data-fit-mode="free" class="${o.mode!=='paper'?'active':''}">Free size · hug the drawing</button><button data-fit-mode="paper" class="${o.mode==='paper'?'active':''}">Smallest standard sheet</button></div></div>
  <div class="row r3"><label class="fld"><span>Padding (mm)</span><input data-fit="pad" type="number" min="0" max="200" value="${o.pad}"></label><label class="fld"><span>Round up to</span><select data-fit="round">${opt(1,'1 mm',o.round)}${opt(5,'5 mm',o.round)}${opt(10,'10 mm',o.round)}${opt(25,'25 mm',o.round)}</select></label><label class="fld"><span>Border inset (margin mm)</span><input data-fit="margin" type="number" min="0" max="60" value="${o.margin}"></label></div>
  <div class="row"><label class="fld"><span>Orientation (standard sheet)</span><select data-fit="orient">${opt('auto','Best fit',o.orient)}${opt('keep','Keep current',o.orient)}</select></label><span></span></div>
  <label class="check"><input type="checkbox" data-fit="reserve" ${o.reserve?'checked':''}>Keep room for the title block and legend</label>
  <label class="check"><input type="checkbox" data-fit="keep" ${o.keep?'checked':''}>Keep hugging the drawing as I edit (Auto-size: Hug drawing)</label>
  <p class="fitResult" id="fitResult"></p>
  <footer><button data-close>Cancel</button><button class="primary" data-fit-apply>Fit page</button></footer>`);
  let mode=o.mode==='paper'?'paper':'free';
  const read=()=>{const r={mode};d.querySelectorAll('[data-fit]').forEach(i=>{r[i.dataset.fit]=i.type==='checkbox'?i.checked:i.type==='number'?Math.max(0,+i.value||0):i.value});r.round=+r.round||5;return r};
  const preview=()=>{const r=read(),copy=C.copy(p);copy.margin=r.margin;const res=Constraints.fitPage(copy,S.doc,r),[w,h]=C.dimensions(copy);$('fitResult').innerHTML=res?`Page will be <b>${copy.paper==='Custom'?`${Math.round(w)} × ${Math.round(h)} mm (custom)`:copy.paper+' '+copy.orientation} </b>· now ${p.paper==='Custom'?p.customW+' × '+p.customH+' mm':p.paper+' '+p.orientation}`:'There is nothing on this page to fit.'};
  d.oninput=preview;d.onchange=preview;preview();
  d.onclick=e=>{if(e.target.closest('[data-close]'))return closeDialog();const m=e.target.closest('[data-fit-mode]');if(m){mode=m.dataset.fitMode;d.querySelectorAll('[data-fit-mode]').forEach(b=>b.classList.toggle('active',b===m));preview();return}
    if(e.target.closest('[data-fit-apply]')){const r=read();closeDialog();S.quietResize=true;mutate(()=>{p.margin=r.margin;p.fit={mode:r.mode,pad:r.pad,round:r.round,orient:r.orient,reserve:r.reserve};Constraints.fitPage(p,S.doc,p.fit);p.autoSize=r.keep?'fit':true});S.quietResize=false;fit();notify(`Page fitted: ${p.paper==='Custom'?p.customW+' × '+p.customH+' mm':p.paper+' '+p.orientation}${r.keep?' — and it will keep hugging the drawing.':'.'}`)}}}
